#!/usr/bin/env node
/**
 * Differential harness: run the reference executable and the Node port with
 * identical argv and compare stdout, stderr and exit code byte for byte.
 *
 * The PyInstaller banner embeds the process id, so that one number is
 * normalised before comparing. Everything else must match exactly.
 */

import { spawnSync } from 'node:child_process';

const EXE = '/workspace/dataset/test17_executable';
const PORT = ['/output/test17.mjs'];

const normalise = (text) => text.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');

export function runPair(argv) {
  const a = spawnSync(EXE, argv, { encoding: 'latin1', maxBuffer: 1 << 26 });
  const b = spawnSync(process.execPath, [...PORT, ...argv], { encoding: 'latin1', maxBuffer: 1 << 26 });
  return {
    argv,
    ok: a.stdout === b.stdout
      && normalise(a.stderr) === normalise(b.stderr)
      && a.status === b.status,
    ref: { stdout: a.stdout, stderr: normalise(a.stderr), status: a.status },
    port: { stdout: b.stdout, stderr: normalise(b.stderr), status: b.status },
  };
}

function show(result) {
  const { ref, port } = result;
  console.log(`\nMISMATCH argv=${JSON.stringify(result.argv)}`);
  if (ref.stdout !== port.stdout) {
    console.log(`  stdout ref : ${JSON.stringify(ref.stdout)}`);
    console.log(`  stdout port: ${JSON.stringify(port.stdout)}`);
  }
  if (ref.stderr !== port.stderr) {
    console.log(`  stderr ref : ${JSON.stringify(ref.stderr)}`);
    console.log(`  stderr port: ${JSON.stringify(port.stderr)}`);
  }
  if (ref.status !== port.status) {
    console.log(`  exit ref=${ref.status} port=${port.status}`);
  }
}

/** @param {string[][]} cases */
export function compareAll(cases, label = 'cases') {
  let pass = 0;
  const failures = [];
  for (const argv of cases) {
    const result = runPair(argv);
    if (result.ok) pass += 1;
    else failures.push(result);
  }
  for (const failure of failures) show(failure);
  console.log(`\n${label}: ${pass}/${cases.length} match, ${failures.length} mismatch`);
  return failures.length;
}

#!/usr/bin/env node
/**
 * Node.js port of /workspace/dataset/construct/test17.py.
 *
 * The Python original builds seven little-endian fields with `construct` and
 * prints each resulting bytes object. This file keeps the same statement order
 * so that a failure part-way through produces the same traceback - the
 * `atSourceLine` numbers are the line numbers of the corresponding statements
 * in the Python source, which the frozen build reports on error.
 *
 * Usage:
 *   node test17.mjs --a INT --b INT --c STR --d INT --e STR --f INT --g INT
 */

import { ArgumentParser, HelpRequested, ParserError, int, str } from './lib/argparse/index.mjs';
import { Bytes, Int8ul, Int16ul } from './lib/construct/index.mjs';
import { PyException } from './lib/python/exceptions.mjs';
import { encodeUtf8 } from './lib/python/codec.mjs';
import { pyMod } from './lib/python/int.mjs';
import { pyBytesRepr } from './lib/python/repr.mjs';
import { getPythonArgv } from './lib/runtime/argv.mjs';
import { PROG_NAME } from './lib/runtime/config.mjs';
import { flush, printLine, writeStderr, writeStdout } from './lib/runtime/stdio.mjs';
import { atSourceLine, renderTraceback } from './lib/runtime/traceback.mjs';

const BYTE_MODULUS = 256n;

function buildParser() {
  const parser = new ArgumentParser(PROG_NAME);
  parser.addArgument(['--a'], { type: int, required: true });
  parser.addArgument(['--b'], { type: int, required: true });
  parser.addArgument(['--c'], { type: str, required: true });
  parser.addArgument(['--d'], { type: int, required: true });
  parser.addArgument(['--e'], { type: str, required: true });
  parser.addArgument(['--f'], { type: int, required: true });
  parser.addArgument(['--g'], { type: int, required: true });
  return parser;
}

function main() {
  const args = buildParser().parseArgs(getPythonArgv());

  const format1 = atSourceLine(16, () => Int8ul.build(args.a)); // 构建头字节
  const format2 = atSourceLine(17, () => Int16ul.build(args.b)); // 构建长度字段
  const format3 = atSourceLine(18, () => Bytes(args.d).build(encodeUtf8(args.c))); // 构建第一个数据块
  const format4 = atSourceLine(19, () => Int8ul.build(args.f)); // 构建分隔符
  const format5 = atSourceLine(20, () => Bytes(args.g).build(encodeUtf8(args.e))); // 构建第二个数据块
  // 构建校验和，确保在字节范围内
  const format6 = atSourceLine(21, () => Int8ul.build(pyMod(args.f + args.g, BYTE_MODULUS)));
  // 构建最终校验，确保在字节范围内
  const format7 = atSourceLine(22, () => Int8ul.build(pyMod(args.a + args.b, BYTE_MODULUS)));

  printLine(pyBytesRepr(format1));
  printLine(pyBytesRepr(format2));
  printLine(pyBytesRepr(format3));
  printLine(pyBytesRepr(format4));
  printLine(pyBytesRepr(format5));
  printLine(pyBytesRepr(format6));
  printLine(pyBytesRepr(format7));
}

try {
  main();
  flush(0);
} catch (err) {
  if (err instanceof HelpRequested) {
    writeStdout(err.text);
    flush(0);
  } else if (err instanceof ParserError) {
    writeStderr(err.render());
    flush(2);
  } else if (err instanceof PyException) {
    writeStderr(renderTraceback(err));
    flush(1);
  } else {
    throw err;
  }
}

